import numpy as np

def ada_mismatch(a, b, batas=0.3):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    penyebut = np.sqrt((np.var(a) + np.var(b)) / 2)
    if penyebut == 0:
        return False
    return bool(abs(a.mean() - b.mean()) / penyebut > batas)

