import numpy as np

def inflasi_best_of_n(true_acc, n_dev, n_models, trials, seed):
    rng = np.random.default_rng(seed)
    acc = rng.binomial(n_dev, true_acc, size=(trials, n_models)) / n_dev
    return float((acc.max(axis=1) - true_acc).mean())

